// === Tab: mySketch ===
// Hair Simulation

let chains = [];
const headRadius = 150;
const hairNum = 100;
const hairSegmentLength = 20;
const gravity = 1.25;
const damping = 0.98;
const substeps = 5;

class Chain {
  constructor(offset, type) {
    this.offset = offset;
    this.type = type; // "hair" or "earring"
    this.segments = [];

    // === Auto parameters depending on type ===
    if (type === "hair") {
      // Hair parameters
      this.segmentLength = hairSegmentLength + random();
      // Compute number of segments automatically
      const rawLen = -offset.y + headRadius * 2;
      this.numSegments = int((rawLen / this.segmentLength) * 1);
    } else if (type === "earring") {
      // Earring parameters
      this.segmentLength = 25;
      this.numSegments = 3;
    }

    // === Initialize segments ===
    const init = createVector();
    for (let i = 0; i < this.numSegments; i++) {
      this.segments.push({
        pos: init.copy(),
        prev: init.copy(),
      });
    }
  }

  // Verlet integration
  update() {
    for (let i =1; i < this.segments.length; i++) {
      const s = this.segments[i];
      const vel = p5.Vector.sub(s.pos, s.prev).mult(damping);
      s.prev = s.pos.copy();
      s.pos.add(vel);
      s.pos.y += gravity;
    }

    const baseX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + this.offset.x;
    const baseY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + this.offset.y;

    for (let i = 0; i < substeps; i++) {
      this.constrain(baseX, baseY);
    }
  }

  // Distance constraints
  constrain(baseX, baseY) {
    this.segments[0].pos.x = baseX;
    this.segments[0].pos.y = baseY;

    let previous = this.segments[0];
    for (let i = 1; i < this.segments.length; i++) {
      const current = this.segments[i];
      const dir = p5.Vector.sub(current.pos, previous.pos);
      const dis = dir.mag();
      const diff = this.segmentLength - dis;
      dir.normalize().mult(diff * 0.5);
      previous.pos.sub(dir);
      current.pos.add(dir);
      previous = current;
    }
  }

  show() {
    beginShape();
    this.segments.forEach((s) => vertex(s.pos.x, s.pos.y));
    endShape();

    // --- Draw earring tip ---
    if (this.type === "earring") {
      const last = this.segments[this.segments.length - 1];
      const prev = this.segments[this.segments.length - 2];
      const dir = p5.Vector.sub(last.pos, prev.pos);
      const angle = atan2(dir.y, dir.x);

      push();
      translate(last.pos);
      rotate(angle - PI / 2);
      const s = 20;
      triangle(0, 0, -s / 2, s, s / 2, s);
      pop();
    }
  }
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  noFill();

  // --- Create hair chains ---
  for (let i = 0; i < hairNum; i++) {
    const offset = createVector(1.0)
      .mult(headRadius)
      .rotate((i / hairNum) * PI + PI);
    chains.push(new Chain(offset, "hair"));
  }

  // --- Earrings ---
  const x = headRadius * 1.2;
  const y = headRadius / 2;
  chains.push(new Chain(createVector(-x, y), "earring"));
  chains.push(new Chain(createVector(x, y), "earring"));
}

function draw() {
  background(255);
  for (const c of chains) {
    c.update();
    c.show();
  }
}


